#include <stdio.h>#include <stdlib.h>#include <string.h>#include "256.h"#include "FileStuff.h"#include "BMP.h"OSErr putPreTexture ( Str255 thePlugFileName );OSErr putPreTexture ( Str255 thePlugFileName ){//----------------------------------vars--------------------------------------------------	short		thePlugFileRef;	OSErr		theError;	FSSpec		thePlugFSSpec;	char	*theTexture;	long	theSize, theWidth, theHeight;	Myth256Palette thePalette;//----------------------------------------------------------------------------------------	// new plug file	theError = FSMakeFSSpec (0L, 0L, thePlugFileName, &thePlugFSSpec);	if ( theError != noErr )		return theError;	theError = FSpOpenDF ( &thePlugFSSpec, fsCurPerm, &thePlugFileRef );	if ( theError != noErr )		return theError;	theWidth = 377;	theHeight = 190;	theSize = theWidth * theHeight;	theTexture = (char *) NewPtr (theSize);	if ( theTexture == nil ){		FSClose ( thePlugFileRef );		return -1;	}	FileSeek ( thePlugFileRef, 384L );					// get the current palette.	FileRead ( &thePalette, 2080L, thePlugFileRef );	theError = readBMP ( "\p:Graphics.in:pregame.bmp", theWidth, theHeight, &thePalette, theTexture );	if ( theError != noErr ){		DisposePtr ( (Ptr) theTexture );		FSClose ( thePlugFileRef );		return theError;	}	FileSeek ( thePlugFileRef, 384L );	FileWrite ( &thePalette, 2080L, thePlugFileRef );	FileSeek ( thePlugFileRef, 4072L );	FileWrite ( theTexture, theSize, thePlugFileRef );	DisposePtr ( theTexture );	FSClose ( thePlugFileRef );	return	noErr;}